bool extract_socket_address_and_port(struct pool *pool, char *url) {
    char *start = url;
    char *end = NULL;
    char *colon = NULL;
    char *address = NULL;
    char *port = NULL;
    size_t address_len = 0;
    size_t port_len = 0;

    if (!pool || !url) {
        return false;
    }

    // Skip leading whitespace
    while (*start && isspace(*start)) {
        start++;
    }

    // Check for IPv6 address (enclosed in brackets)
    if (*start == '[') {
        start++;
        end = strchr(start, ']');
        if (!end) {
            return false;
        }
        start++;
    }

    // Find the colon separating address and port
    colon = strchr(start, ':');

    if (colon) {
        // Port is present
        address_len = colon - start;
        port_len = strlen(colon + 1);
        address = (char *)malloc(address_len + 1);
        port = (char *)malloc(port_len + 1);

        if (!address || !port) {
            free(address);
            free(port);
            return false;
        }

        strncpy(address, start, address_len);
        address[address_len] = '\0';
        strncpy(port, colon + 1, port_len);
        port[port_len] = '\0';
    } else {
        // No port specified, use default port
        address_len = strlen(start);
        address = (char *)malloc(address_len + 1);
        if (!address) {
            return false;
        }
        strncpy(address, start, address_len);
        address[address_len] = '\0';
        port = (char *)malloc(6); // Max length for 5-digit port number
        if (!port) {
            free(address);
            return false;
        }
        strncpy(port, "80", 2); // Default port
        port[2] = '\0';
    }

    // Store the extracted values in the pool
    pool->socket_address = address;
    pool->port = port;

    return true;
}
